    static bool IsDark(System.Windows.Media.Brush brush)=>brush is SolidColorBrush b&&b.Color.R<80&&b.Color.G<80&&b.Color.B<80;
    static bool IsAssignedGreen(System.Windows.Controls.Button button)=>button.Background is SolidColorBrush b&&b.Color.G>b.Color.R*2&&b.Color.G>b.Color.B;
    static IEnumerable<double> AdjacentGaps(IReadOnlyList<System.Windows.Controls.Button> keys){for(int i=1;i<keys.Count;i++)yield return Canvas.GetLeft(keys[i])-(Canvas.GetLeft(keys[i-1])+keys[i-1].Width);}
    static bool NoOverlaps(IReadOnlyList<System.Windows.Controls.Button> keys){for(int i=0;i<keys.Count;i++)for(int j=i+1;j<keys.Count;j++)if(new Rect(Canvas.GetLeft(keys[i]),Canvas.GetTop(keys[i]),keys[i].Width,keys[i].Height).IntersectsWith(new Rect(Canvas.GetLeft(keys[j]),Canvas.GetTop(keys[j]),keys[j].Width,keys[j].Height)))return false;return true;}
    static double RenderedWidth(FrameworkElement element,Visual ancestor)=>element.TransformToAncestor(ancestor).TransformBounds(new Rect(0,0,element.ActualWidth,element.ActualHeight)).Width;
    static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T item)yield return item;foreach(var nested in Descendants<T>(child))yield return nested;}}
